function bindMessages(){$('sendMsg').onclick=()=>{let text=$('msgText').value.trim(),ex=$('msgExpiry').value;if(!text||!ex)return toast('Message and expiry required');db.messages.unshift({id:'MSG-'+Date.now(),priority:$('msgPriority').value,scope:$('msgScope').value,text,expiresAt:new Date(ex).toISOString(),createdAt:now(),adminId:currentUser().id});log(db,currentUser().id,'SEND_ADMIN_MESSAGE',text);save();showPage('messages')}}
