function bindSettings(){$('saveSettings').onclick=()=>{db.settings.airrepValidityMin=+$('airrepVal').value;db.settings.correctionWindowMin=+$('corrWin').value;db.settings.aviatorCooldownMin=+$('cooldown').value;log(db,currentUser().id,'UPDATE_SETTINGS',JSON.stringify(db.settings));save();toast('Settings saved')};$('backupData').onclick=()=>downloadText('awo_backup.json',JSON.stringify(db,null,2),'application/json');$('restoreBtn').onclick=()=>{let f=$('restoreFile').files[0];if(!f)return toast('Choose backup file');let r=new FileReader();r.onload=()=>{try{db=JSON.parse(r.result);save();toast('Backup restored');route()}catch{toast('Invalid backup')}};r.readAsText(f)};$('saveCal').onclick=()=>{let k=$('calKey').value.trim(),off=+$('calOffset').value;if(!k||!Number.isFinite(off))return toast('Enter device key and offset');db.deviceCal[k]={offset:off,updatedBy:currentUser().id,updatedAt:now()};log(db,currentUser().id,'DEVICE_CALIBRATION',`${k} ${off} hPa`);save();toast('Calibration saved')};$('transferPrimary').onclick=()=>{let me=currentUser(),to=$('primaryTo').value;if(!me.primary)return toast('Only Primary Administrator can transfer authority');if($('primaryPass').value!==me.password)return toast('Incorrect Primary password');if(!to)return toast('Select another Administrator');db.users[to].primary=true;me.primary=false;log(db,me.id,'TRANSFER_PRIMARY_ADMIN',to);save();toast('Primary Administrator transferred');route()}}

function weatherFormHtml(id,src){let prev=latestObservation(id,src),h=db.helipads[id],sel=prev?.weatherCodes||['NIL'];return `<div class="note">Previous values are retained. Submit creates a new complete observation.${prev?`<br><b>Previous:</b> ${fmt(prev.observedAt)} • VIS ${prev.visibility}m • ${(prev.weatherCodes||[]).join(' ')} • ${prev.hillTop} • ${prev.htStatus}${prev.cloudStatus?' + '+prev.cloudStatus:''}`:''}</div>${src==='OUT'?`<label>METAR</label><textarea id="wfMetar">${esc(prev?.metar||'')}</textarea><div id="metarWarn" class="small"></div>`:''}<label>Visibility (metres)</label><select id="wfVis">${[500,800,1000,1500,2000,3000,5000,8000,10000].map(v=>`<option ${+prev?.visibility===v?'selected':''}>${v}</option>`).join('')}<option value="OTHER">OTHER</option></select><input id="wfVisOther" class="hidden" type="number" placeholder="Exact metres"><label>Weather codes (multiple)</label><div class="codeGrid">${WX.map(w=>`<button class="code ${sel.includes(w)?'selected':''}" data-wx="${w}">${w}</button>`).join('')}</div><label>Hill Top</label><div class="choiceRow">${HILL.map(x=>`<button class="choice ${prev?.hillTop===x?'selected':''}" data-hill="${x}">${x}</button>`).join('')}</div><label>HT status (one compulsory)</label><div class="choiceRow">${HT.map(x=>`<button class="choice ${prev?.htStatus===x?'selected':''}" data-ht="${x}">${x}</button>`).join('')}</div><label>AC / ANC (optional, mutually exclusive)</label><div class="choiceRow"><button class="choice ${!prev?.cloudStatus?'selected':''}" data-cloud="">NONE</button><button class="choice ${prev?.cloudStatus==='AC'?'selected':''}" data-cloud="AC">AC</button><button class="choice ${prev?.cloudStatus==='ANC'?'selected':''}" data-cloud="ANC">ANC</button></div><label>Observer colour</label><div class="choiceRow"><button class="choice green ${prev?.observerColour==='GREEN'||!prev?'selected':''}" data-colour="GREEN">GREEN</button><button class="choice yellow ${prev?.observerColour==='YELLOW'?'selected':''}" data-colour="YELLOW">YELLOW</button><button class="choice red ${prev?.observerColour==='RED'?'selected':''}" data-colour="RED">RED</button></div><button class="btn success full" id="wfSubmit" style="margin-top:12px">REVIEW & SUBMIT</button>`}
function renderWeatherForm(container,id,src){$(container).innerHTML=weatherFormHtml(id,src);let one=(sel,attr)=>document.querySelectorAll(sel).forEach(b=>b.onclick=()=>{document.querySelectorAll(sel).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});one('[data-hill]','hill');one('[data-ht]','ht');one('[data-cloud]','cloud');one('[data-colour]','colour');document.querySelectorAll('[data-wx]').forEach(b=>b.onclick=()=>{if(b.dataset.wx==='NIL'){document.querySelectorAll('[data-wx]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}else{document.querySelector('[data-wx="NIL"]')?.classList.remove('selected');b.classList.toggle('selected')}});$('wfVis').onchange=()=>{$('wfVisOther').classList.toggle('hidden',$('wfVis').value!=='OTHER')};if(src==='OUT'){$('wfMetar').oninput=metarCheck;metarCheck()}$('wfSubmit').onclick=()=>reviewObservation(id,src)}
function metarCheck(){let t=$('wfMetar').value,p=latestObservation(currentUser().helipads[0],'OUT')?.metar||'',w=[];let a=t.match(/\b(\d{6})Z\b/),b=p.match(/\b(\d{6})Z\b/);if(a&&b&&a[1]===b[1])w.push('⚠ CAUTION — METAR TIME UNCHANGED. Please verify.');if(!a)w.push('Check observation time group (DDHHMMZ).');$('metarWarn').innerHTML=w.join('<br>')}
function reviewObservation(id,src){let vis=$('wfVis').value==='OTHER'?+$('wfVisOther').value:+$('wfVis').value,weatherCodes=[...document.querySelectorAll('[data-wx].selected')].map(x=>x.dataset.wx),hillTop=document.querySelector('[data-hill].selected')?.dataset.hill,htStatus=document.querySelector('[data-ht].selected')?.dataset.ht,cloudStatus=document.querySelector('[data-cloud].selected')?.dataset.cloud||'',observerColour=document.querySelector('[data-colour].selected')?.dataset.colour,metar=src==='OUT'?$('wfMetar').value.trim():'';if(!Number.isFinite(vis)||!weatherCodes.length||!hillTop||!htStatus||!observerColour||(src==='OUT'&&!metar))return toast('Complete all required fields');let h=db.helipads[id],data={id:'OBS-'+Date.now(),helipadId:id,sourceUserId:currentUser().id,source:src,observedAt:now(),submittedAt:now(),visibility:vis,weatherCodes,hillTop,htStatus,cloudStatus,observerColour,metar};data.systemColour=calcColour(h,data);openModal('REVIEW SUBMISSION',`<div class="note"><b>${id}</b><br>VIS ${vis} m • ${weatherCodes.join(' ')} • ${hillTop} • ${htStatus}${cloudStatus?' + '+cloudStatus:''}<br>${src==='OUT'?esc(metar):''}<br>Observer: ${observerColour} • System: ${data.systemColour}</div><label><input id="confirmWeather" type="checkbox" checked style="width:auto;min-height:auto"> Submit complete weather observation</label>${src==='OUT'?`<label><input id="confirmImages" type="checkbox" checked disabled style="width:auto;min-height:auto"> Complete required imagery after weather submission</label>`:''}<button class="btn success full" id="finalObs">FINAL SUBMIT</button>`);$('finalObs').onclick=()=>{if(!$('confirmWeather').checked)return toast('Weather submission must be selected');db.observations.push(data);log(db,currentUser().id,'SUBMIT_OBSERVATION',`${id} ${src} ${data.systemColour}`);save();closeModal();toast('Observation submitted');if(src==='IN')showPage('inEntry');else showPage('outCamera')}}
function bindInEntry(){let load=()=>{let id=$('inHel').value,h=db.helipads[id];$('inEntryVisuals').innerHTML=`<div class="grid g2"><div><h3>REFERENCE IMAGES</h3><div class="imgGrid">${h.views.filter(v=>v.reference).map(v=>`<div class="imgCard"><b>${v.label}</b><img src="${v.reference}"></div>`).join('')||'No reference images'}</div></div><div><h3>LATEST IMAGES</h3><div class="imgGrid">${latestImages(id).map(imageCardHtml).join('')||'No latest images'}</div></div></div>`;renderWeatherForm('inForm',id,'IN')};$('inHel').onchange=load;load()}
function bindInImages(){let render=()=>{let h=db.helipads[$('inImgHel').value];$('inImagesBox').innerHTML=`<h3>Reference Images</h3><div class="imgGrid">${h.views.map(v=>`<div class="imgCard"><b>${v.label}</b>${v.reference?`<img src="${v.reference}">`:'<div class="note">No reference</div>'}</div>`).join('')}</div><h3>Latest Images</h3><div class="imgGrid">${latestImages(h.id).map(imageCardHtml).join('')||'No operational images'}</div><button class="btn purple" id="requestReimage">REQUEST NEW IMAGE(S)</button>`;$('requestReimage').onclick=()=>{openModal('REQUEST NEW IMAGES',`<label>Select views</label><div class="assignGrid">${h.views.map(v=>`<button class="chip" data-rv="${v.id}">${v.label}</button>`).join('')}<button class="chip" id="allViews">ALL VIEWS</button></div><label>Optional reason</label><select id="reReason"><option value="">No reason</option><option>Blurred</option><option>Too Dark</option><option>Obstructed</option><option>Wrong View</option><option>Poor Clarity</option><option>Other</option></select><button class="btn success full" id="sendReReq">SEND REQUEST</button>`);document.querySelectorAll('[data-rv]').forEach(b=>b.onclick=()=>b.classList.toggle('on'));$('allViews').onclick=()=>document.querySelectorAll('[data-rv]').forEach(b=>b.classList.add('on'));$('sendReReq').onclick=()=>{let views=[...document.querySelectorAll('[data-rv].on')].map(x=>x.dataset.rv);if(!views.length)return toast('Select at least one view');db.requests.unshift({id:'REQ-'+Date.now(),type:'IMAGE',helipadId:h.id,views,reason:$('reReason').value,requestedBy:currentUser().id,status:'PENDING',createdAt:now()});log(db,currentUser().id,'REQUEST_NEW_IMAGES',`${h.id} ${views.join(',')}`);save();closeModal();toast('Request sent')}}};$('inImgHel').onchange=render;render()}
function observerHistory(src){let u=currentUser(),a=db.observations.filter(o=>o.source===src&&o.sourceUserId===u.id).sort((a,b)=>new Date(b.observedAt)-new Date(a.observedAt));return pageTitle('WEATHER / IMAGE HISTORY')+`<div class="card"><div class="cardBody">${a.map(o=>`<div class="timelineItem"><b>${o.helipadId} • ${o.systemColour}</b> — ${fmt(o.observedAt)}<br><small>VIS ${o.visibility} • ${(o.weatherCodes||[]).join(' ')} • ${o.hillTop} • ${o.htStatus}</small></div>`).join('')||'No history.'}</div></div>`}

function imageCardHtml(i){return `<div class="imgCard"><b>${i.viewLabel}</b><img src="${i.dataUrl}"><small>${fmt(i.capturedAt)} • ${i.bearing==null?'OVERRIDE':i.bearing+'° '+dirFromBearing(i.bearing)} • ${i.capturedBy}</small></div>`}

let cam={stream:null,facing:'environment',bearing:null,view:null,helipad:null,override:false,overrideReason:'',photo:null,sessionId:null};
async function openCameraFor(viewId){let u=currentUser(),h=db.helipads[(u.helipads||[])[0]],v=h?.views.find(x=>x.id===viewId);if(!h||!v)return;cam.helipad=h;cam.view=v;cam.override=false;cam.photo=null;if(!cam.sessionId)cam.sessionId='SES-'+Date.now();$('cameraTarget').textContent=`TARGET ${v.bearing}° ${dirFromBearing(v.bearing)} • ±${v.tolerance}°`;$('cameraModal').classList.remove('hidden');$('cameraReview').classList.add('hidden');$('cameraStage').classList.remove('hidden');updateWeatherStrip();try{cam.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:cam.facing}},audio:false});$('cameraVideo').srcObject=cam.stream}catch(e){toast('Camera permission unavailable. Use HTTPS and allow camera.',true)}startOrientation();drawRadial()}
function stopCamera(){if(cam.stream)cam.stream.getTracks().forEach(t=>t.stop());cam.stream=null;$('cameraModal').classList.add('hidden')}
$('closeCamera').onclick=stopCamera;$('referenceBtn').onclick=()=>{if(cam.view?.reference)openModal('REFERENCE — '+cam.view.label,`<img src="${cam.view.reference}" style="width:100%;max-height:75vh;object-fit:contain">`);else toast('No reference image uploaded')};$('switchBtn').onclick=async()=>{cam.facing=cam.facing==='environment'?'user':'environment';if(cam.stream)cam.stream.getTracks().forEach(t=>t.stop());try{cam.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:cam.facing},audio:false});$('cameraVideo').srcObject=cam.stream}catch{toast('Unable to switch camera')}};$('overrideBtn').onclick=()=>openModal('BEARING OVERRIDE',`<label>Reason (mandatory)</label><select id="ovReason"><option>Compass/Sensor Issue</option><option>Physical Obstruction</option><option>Safety/Access Restriction</option><option>Other</option></select><button id="confirmOverride" class="btn warn full">CONFIRM OVERRIDE</button>`);document.addEventListener('click',e=>{if(e.target.id==='confirmOverride'){cam.override=true;cam.overrideReason=$('ovReason').value;closeModal();toast('Bearing override enabled')}})
function startOrientation(){let handler=e=>{let b=null;if(typeof e.webkitCompassHeading==='number')b=e.webkitCompassHeading;else if(e.alpha!=null)b=(360-e.alpha+360)%360;if(b!=null){cam.bearing=Math.round(b);updateGuide();drawRadial()}};if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function')DeviceOrientationEvent.requestPermission().then(x=>{if(x==='granted')window.addEventListener('deviceorientation',handler,true)}).catch(()=>{});else{window.addEventListener('deviceorientationabsolute',handler,true);window.addEventListener('deviceorientation',handler,true)}}
function updateGuide(){let target=cam.view?.bearing??0,b=cam.bearing;if(b==null){$('bearingValue').textContent='—°';$('bearingDir').textContent='COMPASS UNAVAILABLE';$('guideTitle').textContent='COMPASS UNAVAILABLE';$('guideArrows').textContent='';$('guide').className='guide out';return}let d=angleDiff(target,b),ad=Math.abs(d),tol=cam.view.tolerance;$('bearingValue').textContent=b+'°';$('bearingDir').textContent=dirFromBearing(b);if(ad<=tol){$('guide').className='guide in';$('guideTitle').textContent='ALIGNED — HOLD STEADY';$('guideArrows').textContent='✓';$('guideSub').textContent='IN RANGE'}else if(ad<=tol+15){$('guide').className='guide near';$('guideTitle').textContent=d>0?'SLIGHTLY RIGHT':'SLIGHTLY LEFT';$('guideArrows').textContent=d>0?'››':'‹‹';$('guideSub').textContent='NEAR TARGET'}else{$('guide').className='guide out';$('guideTitle').textContent=d>0?'TURN RIGHT':'TURN LEFT';$('guideArrows').textContent=d>0?'›››':'‹‹‹';$('guideSub').textContent='MOVE SLOWLY'}}
function drawRadial(ctx=$('radialCanvas').getContext('2d'),w=$('radialCanvas').width,h=$('radialCanvas').height,b=cam.bearing??0,target=cam.view?.bearing??0){ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h-10);ctx.strokeStyle='rgba(255,255,255,.9)';ctx.fillStyle='#fff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,w*.42,Math.PI*1.08,Math.PI*1.92);ctx.stroke();for(let off=-60;off<=60;off+=10){let ang=((off-90)*Math.PI/180),r=w*.42,x=Math.cos(ang)*r,y=Math.sin(ang)*r;ctx.beginPath();ctx.moveTo(x*.96,y*.96);ctx.lineTo(x,y);ctx.stroke();ctx.font='34px Arial';ctx.textAlign='center';ctx.fillText(String((Math.round(b/10)*10+off+360)%360).padStart(3,'0')+'°',Math.cos(ang)*r*.82,Math.sin(ang)*r*.82)}let diff=angleDiff(target,b),ang=((diff-90)*Math.PI/180);ctx.strokeStyle='#ffd21f';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(Math.cos(ang)*w*.33,Math.sin(ang)*w*.33);ctx.lineTo(Math.cos(ang)*w*.43,Math.sin(ang)*w*.43);ctx.stroke();ctx.restore()}
function updateWeatherStrip(){let o=officialObservation(cam.helipad),s=statusFor(cam.helipad),parts=[`HELIPAD ${cam.helipad.id}`,`VIEW ${cam.view.label}`];if(o)parts.push(`VIS ${o.visibility}m`,`WX ${(o.weatherCodes||[]).join(' ')}`,`HILL ${o.hillTop}`,`HT ${o.htStatus}`,`STATUS ${s.status}`);$('weatherStrip').innerHTML=parts.map(x=>`<span>${esc(x)}</span>`).join('')}
$('shutterBtn').onclick=()=>capturePhoto();function capturePhoto(){let video=$('cameraVideo');if(!video.videoWidth)return toast('Camera not ready');let diff=cam.bearing==null?999:Math.abs(angleDiff(cam.view.bearing,cam.bearing)),inRange=diff<=cam.view.tolerance;if(!inRange&&!cam.override)return toast('Move into bearing tolerance or use Bearing Override',true);let c=$('captureCanvas'),ctx=c.getContext('2d'),w=video.videoWidth,h=video.videoHeight;c.width=w;c.height=h;ctx.drawImage(video,0,0,w,h);embedOverlay(ctx,w,h,inRange);cam.photo=c.toDataURL('image/jpeg',.78);$('reviewImage').src=cam.photo;$('reviewMeta').innerHTML=`<b>${cam.helipad.id} • ${cam.view.label}</b><br>Captured: ${new Date().toLocaleString()}<br>Bearing: ${cam.bearing==null?'UNAVAILABLE':cam.bearing+'° '+dirFromBearing(cam.bearing)} • Target ${cam.view.bearing}° ±${cam.view.tolerance}°<br>Status: ${inRange?'IN RANGE':'BEARING OVERRIDE'} ${cam.override?`• ${esc(cam.overrideReason)}`:''}`;$('cameraStage').classList.add('hidden');$('cameraReview').classList.remove('hidden')}
function embedOverlay(ctx,w,h,inRange){ctx.save();let scale=Math.max(.8,w/1400);ctx.fillStyle='rgba(3,15,27,.78)';ctx.fillRect(20,20,w*.52,85*scale);ctx.fillStyle='#fff';ctx.font=`bold ${28*scale}px Arial`;ctx.fillText(`${cam.helipad.id} — ${cam.view.label}`,40,58*scale);ctx.fillStyle='#ffd21f';ctx.font=`bold ${22*scale}px Arial`;ctx.fillText(`TARGET ${cam.view.bearing}° ${dirFromBearing(cam.view.bearing)} • ±${cam.view.tolerance}°`,40,90*scale);let o=officialObservation(cam.helipad),s=statusFor(cam.helipad);let barH=100*scale;ctx.fillStyle='rgba(3,15,27,.82)';ctx.fillRect(20,h-barH-20,w-40,barH);ctx.fillStyle='#fff';ctx.font=`bold ${20*scale}px Arial`;let info=[];if(o)info=[`VIS ${o.visibility} m`,`WX ${(o.weatherCodes||[]).join(' ')}`,`HILL ${o.hillTop}`,`HT ${o.htStatus}`,`STATUS ${s.status}`];else info=['NO VALID WEATHER'];let x=40;for(let item of info){ctx.fillText(item,x,h-55*scale);x+=ctx.measureText(item).width+42*scale}ctx.fillStyle='#ffd21f';ctx.font=`bold ${46*scale}px Arial`;let btxt=cam.bearing==null?'BEARING OVERRIDE':`${cam.bearing}° ${dirFromBearing(cam.bearing)}`;ctx.fillText(btxt,w*.42,h*.72);ctx.fillStyle='#fff';ctx.font=`${18*scale}px Arial`;if(o?.metar){ctx.fillStyle='rgba(3,15,27,.86)';ctx.fillRect(20,h-barH-58*scale,w-40,34*scale);ctx.fillStyle='#fff';ctx.font=`${15*scale}px Arial`;ctx.fillText('METAR '+o.metar.slice(0,120),40,h-barH-34*scale)}ctx.fillStyle='#fff';ctx.font=`${18*scale}px Arial`;ctx.fillText(new Date().toLocaleString(),40,h-20);ctx.fillText(currentUser().id,w*.72,h-20);ctx.restore()}
$('retakeBtn').onclick=()=>{$('cameraReview').classList.add('hidden');$('cameraStage').classList.remove('hidden');cam.photo=null};$('usePhotoBtn').onclick=()=>{let u=currentUser(),source=u.role==='OBSERVER'?'OUT':'CAP',sid=cam.sessionId||('SES-'+Date.now()),hadPrevious=latestImages(cam.helipad.id).length>0,meta={id:'IMG-'+Date.now(),sessionId:sid,helipadId:cam.helipad.id,viewId:cam.view.id,viewLabel:cam.view.label,capturedBy:u.id,source,capturedAt:now(),submittedAt:now(),bearing:cam.bearing,targetBearing:cam.view.bearing,tolerance:cam.view.tolerance,bearingOverride:cam.override,overrideReason:cam.overrideReason,dataUrl:cam.photo};db.images.push(meta);let ses=db.sessions.find(x=>x.id===sid);if(!ses){ses={id:sid,helipadId:cam.helipad.id,userId:u.id,source,submittedAt:now(),complete:false,scheduled:false};db.sessions.push(ses)}let same=db.images.filter(i=>i.sessionId===sid),required=cam.helipad.views.filter(v=>v.active!==false).length;ses.complete=new Set(same.map(i=>i.viewId)).size>=required;if(hadPrevious&&!ses.complete)cam.helipad.mixedLatched=true;if(ses.complete){let task=db.tasks.find(t=>t.type==='IMAGE'&&t.helipadId===cam.helipad.id&&!['COMPLETE','CANCELLED'].includes(t.status)&&Math.abs(new Date(t.dueAt)-Date.now())<=60*60000);if(task){ses.scheduled=true;task.status='COMPLETE';task.completedAt=now();cam.helipad.mixedLatched=false}cam.sessionId=null}log(db,u.id,'CAPTURE_IMAGE',`${cam.helipad.id} ${cam.view.id} ${cam.bearing??'OVERRIDE'}`);save();stopCamera();toast('Image saved and available immediately');showPage(u.role==='CAPTURER'?'capHome':'outCamera')}

function bindAvHome(){let render=()=>{let u=currentUser(),q=$('avSearch').value.toUpperCase(),f=$('avFilter').value,shown=u.displayHelipads||u.helipads;$('avRows').innerHTML=shown.filter(id=>id.includes(q)).map(id=>db.helipads[id]).filter(Boolean).filter(h=>f==='ALL'||statusFor(h).status===f).map(h=>{let s=statusFor(h),o=s.obs;return `<tr class="clickable" data-avhel="${h.id}"><td><b>${h.name}</b></td><td>${o?.visibility??'—'}</td><td>${o?(o.weatherCodes||[]).join(' '):'—'}</td><td>${o?.hillTop??'—'}</td><td>${o?.htStatus??'—'}</td><td>${o?.cloudStatus||''}</td><td class="status-${s.status}">${s.status}</td><td>${o?.source??'—'}</td><td>📷 ${imageStatus(h)}</td><td>${tm(o?.observedAt)}</td></tr>`}).join('');document.querySelectorAll('[data-avhel]').forEach(r=>r.onclick=()=>aviatorDetail(r.dataset.avhel))};$('avSearch').oninput=render;$('avFilter').onchange=render;$('manageAvHel').onclick=()=>manageAviatorDisplay();render()}
function manageAviatorDisplay(){let u=currentUser(),shown=u.displayHelipads||[...u.helipads];openModal('DISPLAYED HELIPADS',`<div class="assignGrid">${u.helipads.map(id=>`<button class="chip ${shown.includes(id)?'on':''}" data-disp="${id}">${id}</button>`).join('')}</div><button class="btn success full" id="saveDisp">SAVE</button>`);document.querySelectorAll('[data-disp]').forEach(b=>b.onclick=()=>b.classList.toggle('on'));$('saveDisp').onclick=()=>{u.displayHelipads=[...document.querySelectorAll('[data-disp].on')].map(x=>x.dataset.disp);save();closeModal();showPage('avHome')}}
function aviatorDetail(id){let h=db.helipads[id],s=statusFor(h),o=s.obs,imgs=latestImages(id),hist=db.observations.filter(x=>x.helipadId===id).sort((a,b)=>new Date(b.observedAt)-new Date(a.observedAt)).slice(0,5),ars=db.airreps.filter(a=>[a.from,a.to].includes(id)&&new Date(a.expiresAt)>new Date()).sort((a,b)=>new Date(b.submittedAt)-new Date(a.submittedAt));openModal(h.name,`<div class="tabs"><button class="tab active">OVERVIEW</button></div><div class="grid g2"><div><div class="timelineItem status-${s.status}"><b>${s.status}</b><br>${o?`VIS ${o.visibility}m • ${(o.weatherCodes||[]).join(' ')} • ${o.hillTop} • ${o.htStatus}`:'NO VALID WEATHER'}</div><h3>VALID AIRREPs</h3>${ars.map(a=>`<div class="timelineItem"><b>${a.from} → ${a.to}</b><br>${esc(a.remarks)}<br><small>${fmt(a.submittedAt)} • ${a.aviatorId}</small></div>`).join('')||'None'}</div><div><h3>REFERENCE IMAGES</h3><div class="imgGrid">${h.views.map(v=>`<div class="imgCard"><b>${v.label}</b>${v.reference?`<img src="${v.reference}">`:'No reference'}</div>`).join('')}</div></div></div><h3>LATEST OPERATIONAL IMAGES — ${imageStatus(h)}</h3><div class="imgGrid">${imgs.map(imageCardHtml).join('')||'No image'}</div><h3>PREVIOUS 5 WEATHER OBSERVATIONS</h3>${hist.map(x=>`<div class="timelineItem"><b>${fmt(x.observedAt)} • ${x.systemColour}</b><br>VIS ${x.visibility} • ${(x.weatherCodes||[]).join(' ')} • ${x.hillTop} • ${x.htStatus}</div>`).join('')}<div class="row"><button class="btn primary" id="avReqLatest">REQUEST LATEST IMAGE</button><button class="btn" id="avNotif">NOTIFICATION SETTINGS</button></div>`);$('avReqLatest').onclick=()=>requestLatestImage(id);$('avNotif').onclick=()=>openAlertSettings(id)}
function requestLatestImage(id){let u=currentUser(),last=db.requests.find(r=>r.requestedBy===u.id&&r.helipadId===id&&r.status==='PENDING');if(last&&Date.now()-new Date(last.createdAt)<db.settings.aviatorCooldownMin*60000)return toast('Existing request is still pending');let h=db.helipads[id];openModal('REQUEST LATEST IMAGE',`<div class="assignGrid">${h.views.map(v=>`<button class="chip" data-rview="${v.id}">${v.label}</button>`).join('')}<button class="chip" id="allR">ALL VIEWS</button></div><label>Optional reason</label><textarea id="rMsg"></textarea><button class="btn success full" id="sendImgReq">SEND REQUEST</button>`);document.querySelectorAll('[data-rview]').forEach(b=>b.onclick=()=>b.classList.toggle('on'));$('allR').onclick=()=>document.querySelectorAll('[data-rview]').forEach(b=>b.classList.add('on'));$('sendImgReq').onclick=()=>{let views=[...document.querySelectorAll('[data-rview].on')].map(x=>x.dataset.rview);if(!views.length)return toast('Select view(s)');db.requests.unshift({id:'REQ-'+Date.now(),type:'IMAGE',helipadId:id,views,reason:$('rMsg').value,requestedBy:u.id,status:'PENDING',createdAt:now()});log(db,u.id,'AVIATOR_REQUEST_IMAGE',`${id} ${views.join(',')}`);save();closeModal();toast('Request sent')}}
function openAlertSettings(id){let u=currentUser();u.alerts=u.alerts||{};let a=u.alerts[id]||{statuses:['RED','PURPLE'],returnGreen:false,audible:false};openModal('NOTIFICATIONS — '+id,`<label>Status notifications</label><div class="assignGrid">${['YELLOW','RED','GREY','PURPLE'].map(s=>`<button class="chip ${a.statuses.includes(s)?'on':''}" data-ast="${s}">${s}</button>`).join('')}</div><label><input id="retGreen" type="checkbox" ${a.returnGreen?'checked':''} style="width:auto;min-height:auto"> Notify when status returns to GREEN</label><label><input id="audible" type="checkbox" ${a.audible?'checked':''} style="width:auto;min-height:auto"> Audible / ringing alert</label><button class="btn success full" id="saveAlert">SAVE</button>`);document.querySelectorAll('[data-ast]').forEach(b=>b.onclick=()=>b.classList.toggle('on'));$('saveAlert').onclick=()=>{u.alerts[id]={statuses:[...document.querySelectorAll('[data-ast].on')].map(x=>x.dataset.ast),returnGreen:$('retGreen').checked,audible:$('audible').checked};save();closeModal();toast('Alert settings saved')}}
function bindAirrep(){$('submitAirrep').onclick=()=>{let from=$('arFrom').value,to=$('arTo').value;if(from===to)return toast('Select two different helipads');let a={id:'AR-'+Date.now(),aviatorId:currentUser().id,from,to,remarks:$('arRemarks').value.trim(),t1:$('arT1').value,pType1:$('arPType1').value,p1:$('arP1').value,t2:$('arT2').value,pType2:$('arPType2').value,p2:$('arP2').value,submittedAt:now(),expiresAt:new Date(Date.now()+db.settings.airrepValidityMin*60000).toISOString()};db.airreps.unshift(a);log(db,currentUser().id,'SUBMIT_AIRREP',`${from}->${to}`);save();toast('AIRREP submitted');showPage('avAirrep')}}
function airrepCards(){return db.airreps.slice(0,20).map(a=>`<div class="timelineItem"><b>${a.from} → ${a.to}</b><br>${esc(a.remarks)}<br><small>${a.t1}°C / ${a.p1} ${a.pType1} • ${a.t2}°C / ${a.p2} ${a.pType2} • ${fmt(a.submittedAt)}</small></div>`).join('')||'No AIRREPs.'}
function airrepTable(admin=false){return `<div class="card"><div class="cardBody"><div class="tableWrap"><table><thead><tr><th>TIME</th><th>FROM</th><th>TO</th><th>AVIATOR</th><th>REMARKS</th><th>VALID</th></tr></thead><tbody>${db.airreps.map(a=>`<tr><td>${fmt(a.submittedAt)}</td><td>${a.from}</td><td>${a.to}</td><td>${a.aviatorId}</td><td>${esc(a.remarks)}</td><td>${new Date(a.expiresAt)>new Date()?'YES':'OLD AIRREP'}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function bindCompare(){let sel=[];document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{b.classList.toggle('on');sel=[...document.querySelectorAll('[data-compare].on')].map(x=>x.dataset.compare)});$('doCompare').onclick=()=>{if(sel.length<2)return toast('Select at least two helipads');$('compareResult').innerHTML=`<div class="tableWrap"><table><thead><tr><th>HELIPAD</th><th>VIS</th><th>WX</th><th>HILL</th><th>STATUS</th><th>IMAGE</th></tr></thead><tbody>${sel.map(id=>{let h=db.helipads[id],s=statusFor(h),o=s.obs;return `<tr><td>${id}</td><td>${o?.visibility??'—'}</td><td>${o?(o.weatherCodes||[]).join(' '):'—'}</td><td>${o?.hillTop??'—'}</td><td class="status-${s.status}">${s.status}</td><td>${imageStatus(h)}</td></tr>`}).join('')}</tbody></table></div>${$('compareImages').checked?`<div class="grid g2" style="margin-top:10px">${sel.map(id=>`<div><h3>${id}</h3><div class="imgGrid">${latestImages(id).map(imageCardHtml).join('')||'No images'}</div></div>`).join('')}</div>`:''}`}}
function bindAvAlerts(){let u=currentUser();let render=()=>{$('avAlertList').innerHTML=u.helipads.map(id=>{let a=u.alerts?.[id];return `<div class="timelineItem"><b>${id}</b><br>${a?`Statuses: ${a.statuses.join(', ')} • Return Green: ${a.returnGreen?'YES':'NO'} • ${a.audible?'AUDIBLE':'NORMAL'}`:'No personal alerts'}<br><button class="btn" data-edit-alert="${id}">EDIT</button></div>`}).join('');document.querySelectorAll('[data-edit-alert]').forEach(b=>b.onclick=()=>openAlertSettings(b.dataset.editAlert));$('profileList').innerHTML=db.profiles.filter(p=>p.owner===u.id).map(p=>`<div class="timelineItem"><b>${p.name}</b> • ${p.active?'ACTIVE':'OFF'}<br><button class="btn" data-toggle-prof="${p.id}">${p.active?'DEACTIVATE':'ACTIVATE'}</button></div>`).join('')||'No profiles.';document.querySelectorAll('[data-toggle-prof]').forEach(b=>b.onclick=()=>{let p=db.profiles.find(x=>x.id===b.dataset.toggleProf);p.active=!p.active;save();render()})};$('saveProfile').onclick=()=>{let name=$('profileName').value.trim();if(!name)return toast('Enter profile name');db.profiles.push({id:'PROF-'+Date.now(),owner:u.id,name,active:false,alerts:JSON.parse(JSON.stringify(u.alerts||{})),sharedFrom:null});save();render()};render()}
function bindPeer(){let render=()=>{let u=currentUser(),a=db.peerRequests.filter(r=>r.to===u.id||r.from===u.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));$('peerList').innerHTML=a.map(r=>`<div class="timelineItem"><b>${r.from} → ${r.to} • ${r.helipadId}</b><br>${r.type} • ${r.status}<br><small>${esc(r.message||'')}</small>${r.to===u.id&&r.status==='PENDING'?`<div class="row"><button class="btn success" data-peer-accept="${r.id}">ACCEPT</button><button class="btn danger" data-peer-reject="${r.id}">REJECT</button></div>`:''}</div>`).join('')||'No pilot-to-pilot requests.';document.querySelectorAll('[data-peer-accept]').forEach(b=>b.onclick=()=>{let r=db.peerRequests.find(x=>x.id===b.dataset.peerAccept);r.status='ACCEPTED';r.respondedAt=now();save();render();toast('Request accepted')});document.querySelectorAll('[data-peer-reject]').forEach(b=>b.onclick=()=>{let r=db.peerRequests.find(x=>x.id===b.dataset.peerReject);r.status='REJECTED';r.respondedAt=now();save();render()})};$('sendPeer').onclick=()=>{let to=$('peerTo').value;if(!to)return toast('No eligible Aviator');db.peerRequests.unshift({id:'PEER-'+Date.now(),from:currentUser().id,to,helipadId:$('peerHel').value,type:$('peerType').value,message:$('peerMsg').value,status:'PENDING',createdAt:now()});log(db,currentUser().id,'PILOT_TO_PILOT_REQUEST',`${to} ${$('peerHel').value}`);save();render();toast('Request sent')};render()}

function refreshNotifications(){let u=currentUser();if(!u)return;let due=db.tasks.filter(t=>t.assignedUserId===u.id&&!['COMPLETE','CANCELLED'].includes(t.status)&&new Date(t.reminderAt)<=new Date()&&new Date(t.dueAt)>=new Date(Date.now()-3600000));due.forEach(t=>{if(!t._shown){t._shown=true;toast(`${t.type} due at ${tm(t.dueAt)} — ${t.helipadId}`,true)}});db.messages.filter(m=>new Date(m.expiresAt)>new Date()&&(m.scope==='ALL'||m.scope===u.role)).forEach(m=>{if(!m.seenBy?.includes(u.id)){m.seenBy=m.seenBy||[];m.seenBy.push(u.id);toast(`${m.priority}: ${m.text}`,m.priority==='URGENT')}});save()}
setInterval(refreshNotifications,30000);window.addEventListener('online',()=>{$('syncBadge').textContent='ONLINE • LOCAL MODE';toast('Connection available')});window.addEventListener('offline',()=>{$('syncBadge').textContent='OFFLINE READY'});
function downloadText(name,text,type='text/plain'){let b=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function toSpreadsheetXml(rows){let keys=rows.length?Object.keys(rows[0]):[];let cells=keys.map(k=>`<Cell><Data ss:Type="String">${esc(k)}</Data></Cell>`).join('');let body=rows.map(r=>`<Row>${keys.map(k=>`<Cell><Data ss:Type="String">${esc(r[k])}</Data></Cell>`).join('')}</Row>`).join('');return `<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Audit"><Table><Row>${cells}</Row>${body}</Table></Worksheet></Workbook>`}
save();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js?v=4.0.0').catch(()=>{}));
